(()=>{
 const layer=$('oceanEffects'),mode=$('effectsMode')||document.createElement('select'),reduced=matchMedia('(prefers-reduced-motion: reduce)');let chosen='auto',low=false,measuring=false,samples=[],last=0,measureStart=0,latestTap=0;
 const hud=document.createElement('output');hud.id='perfHUD';hud.hidden=true;document.querySelector('.screen').append(hud);
 try{chosen=localStorage.getItem('tile-master-effects')||'auto'}catch{}mode.value=chosen;
 function build(){const automaticLow=(navigator.hardwareConcurrency||8)<=4||(navigator.deviceMemory&&navigator.deviceMemory<=4)||navigator.connection?.saveData;low=chosen==='low'||(chosen==='auto'&&automaticLow);const off=chosen==='off'||(chosen==='auto'&&reduced.matches);layer.hidden=off;layer.replaceChildren();layer.dataset.quality=off?'off':low?'low':'normal';if(off)return;
 for(let i=0;i<(low?6:12);i++){const bubble=document.createElement('img');bubble.src='assets/ocean/bubble.svg';bubble.alt='';bubble.className='bubble';const side=i%2,pos=1+(i*7%6);bubble.style.cssText=`left:${side?100-pos-2:pos}%;width:${7+i*7%12}px;--drift:${(i%3-1)*9}px;animation-duration:${18+i*5%17}s;animation-delay:-${i*3.7}s`;layer.append(bubble)}
 for(let i=0;i<(low?2:3);i++){const ray=document.createElement('img');ray.src='assets/ocean/light.svg';ray.alt='';ray.className='lightRay';ray.style.cssText=`left:${8+i*31}%;--angle:${i*6-8}deg;animation-duration:${17+i*6}s;animation-delay:-${i*4}s`;layer.append(ray)}sync()}
 function sync(){layer.classList.toggle('stopped',document.hidden||!$('overlay').hidden||($('settingsPanel')&&!$('settingsPanel').hidden)||($('helpPanel')&&!$('helpPanel').hidden)||(roundActive&&paused));layer.style.setProperty('--fx-height',document.querySelector('.screen').clientHeight+50+'px')}
 mode.onchange=()=>{chosen=mode.value;try{localStorage.setItem('tile-master-effects',chosen)}catch{}build()};reduced.addEventListener('change',build);document.addEventListener('visibilitychange',sync);window.addEventListener('resize',sync);new MutationObserver(sync).observe(document.querySelector('.screen'),{subtree:true,attributes:true,attributeFilter:['hidden']});
 if($('perfButton'))$('perfButton').onclick=()=>{if(measuring)return;measuring=true;hud.hidden=false;hud.textContent='描画計測中（10秒）';samples=[];last=0;measureStart=performance.now();$('perfStats').textContent='10秒間計測中。PLAYで操作も確認できます。';requestAnimationFrame(frame)};
 function frame(time){if(!measuring)return;if(document.hidden){measuring=false;$('perfStats').textContent='タブ非表示のため計測を中止しました';return}if(last&&time-last<500)samples.push(time-last);last=time;if(time-measureStart<10000){requestAnimationFrame(frame);return}measuring=false;const average=samples.reduce((a,b)=>a+b,0)/Math.max(1,samples.length),fps=Math.round(1000/average),sorted=[...samples].sort((a,b)=>a-b),p95=Math.round(sorted[Math.floor(sorted.length*.95)]||0);$('perfStats').textContent=`${layer.dataset.quality} · 約${fps} FPS / フレーム95% ${p95}ms / タップ描画 ${latestTap?Math.round(latestTap)+'ms':'未計測'}`;hud.textContent=$('perfStats').textContent;layer.dataset.fps=fps;layer.dataset.frameP95=p95;layer.dataset.tapMs=Math.round(latestTap);if(chosen==='auto'&&fps<42&&!low){chosen='low';mode.value='low';build();$('perfStats').textContent+=' → 軽量モードへ切替'} }
 document.addEventListener('pointerdown',e=>{if(!measuring||!e.target.closest('.tile'))return;const at=performance.now();requestAnimationFrame(()=>requestAnimationFrame(()=>latestTap=performance.now()-at))},{passive:true});build();sync();
})();
